import{_ as t,o as r,c as d,a6 as a}from"./chunks/framework.Dtv7txdI.js";const b=JSON.parse('{"title":"Lua API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"v1/api/index.md","filePath":"v1/api/index.md","lastUpdated":1787648967000}'),o={name:"v1/api/index.md"};function n(i,e,c,s,h,l){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="lua-api-reference" tabindex="-1">Lua API Reference <a class="header-anchor" href="#lua-api-reference" aria-label="Permalink to “Lua API Reference”">​</a></h1><p>The complete surface Nitr exposes to Lua — one namespace, <code>nitr</code>. Nothing else is registered as a global.</p><p>This page is the <strong>inventory</strong>: every function, what it takes and what it returns. The <a href="./../server/">Server guides</a> are where each one is explained with worked examples.</p><div class="note custom-block github-alert"><p class="custom-block-title">Entries marked with a _std feature_</p><p></p><p>A tag like <em>(std feature: <code>db</code>)</em> means the module needs that name in <code>[std] features</code> — and, for the heavier ones, the matching <a href="./../library/cargo-features">Cargo feature</a> compiled into the binary. See <a href="./../server/configuration/file#std">Configuration → [std]</a>.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">Editor completion</p><p></p><p><code>nitr init</code> writes <code>nitr-types.lua</code>: generated LuaCATS definitions covering everything on this page. Any editor running the <a href="https://luals.github.io/" target="_blank" rel="noreferrer">Lua Language Server</a> picks it up and gives you completion, signatures and inline docs.</p></div><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Application</strong></td><td><a href="#nitr-app"><code>nitr.app</code></a> · <a href="#nitr-cfg"><code>nitr.cfg</code></a> · <a href="#nitr-ext"><code>nitr.ext</code></a></td></tr><tr><td><strong>Responses</strong></td><td><a href="#nitr-json"><code>nitr.json</code></a> · <a href="#nitr-text"><code>nitr.text</code></a> · <a href="#nitr-html"><code>nitr.html</code></a> · <a href="#nitr-redirect"><code>nitr.redirect</code></a> · <a href="#nitr-status"><code>nitr.status</code></a> · <a href="#nitr-error"><code>nitr.error</code></a> · <a href="#nitr-negotiate"><code>nitr.negotiate</code></a> · <a href="#nitr-etag"><code>nitr.etag</code></a> · <a href="#nitr-sse"><code>nitr.sse</code></a></td></tr><tr><td><strong>Security</strong></td><td><a href="#nitr-crypto"><code>nitr.crypto</code></a> · <a href="#nitr-crypto-jwt"><code>nitr.crypto.jwt</code></a> · <a href="#nitr-auth"><code>nitr.auth</code></a> · <a href="#nitr-csrf"><code>nitr.csrf</code></a> · <a href="#nitr-session"><code>nitr.session</code></a></td></tr><tr><td><strong>Data</strong></td><td><a href="#nitr-db"><code>nitr.db</code></a> · <a href="#nitr-cache"><code>nitr.cache</code></a> · <a href="#nitr-validate"><code>nitr.validate</code></a></td></tr><tr><td><strong>I/O</strong></td><td><a href="#nitr-fetch"><code>nitr.fetch</code></a> · <a href="#nitr-await-all"><code>nitr.await_all</code></a> · <a href="#nitr-template"><code>nitr.template</code></a></td></tr><tr><td><strong>Utilities</strong></td><td><a href="#nitr-time"><code>nitr.time</code></a> · <a href="#nitr-base64"><code>nitr.base64</code></a> · <a href="#nitr-path"><code>nitr.path</code></a> · <a href="#nitr-url"><code>nitr.url</code></a> · <a href="#nitr-env"><code>nitr.env</code></a></td></tr><tr><td><strong>Diagnostics</strong></td><td><a href="#nitr-log"><code>nitr.log</code></a> · <a href="#nitr-dbg"><code>nitr.dbg</code></a> · <a href="#nitr-errinfo"><code>nitr.errinfo</code></a></td></tr><tr><td><strong>Testing</strong></td><td><a href="#nitr-test"><code>nitr.test</code></a></td></tr><tr><td><strong>Types</strong></td><td><a href="./types">Request, Response, App, and the rest →</a></td></tr></tbody></table><hr><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to “Application”">​</a></h2><h3 id="nitr-app" tabindex="-1"><code>nitr.app</code> <a class="header-anchor" href="#nitr-app" aria-label="Permalink to “nitr.app”">​</a></h3><p><code>nitr.app() -&gt; nitr.App</code></p><p>Creates the application object the handler script must return. See <a href="./types#nitr-app"><code>nitr.App</code></a> for its methods, and <a href="./../server/routing">Routing</a>.</p><h3 id="nitr-cfg" tabindex="-1"><code>nitr.cfg</code> <a class="header-anchor" href="#nitr-cfg" aria-label="Permalink to “nitr.cfg”">​</a></h3><p><em>(set when a <code>config_script</code> is configured)</em></p><p>The configuration snapshot returned by <code>config.lua</code> — <code>nil</code> without one. Plain data, snapshotted into every state. See <a href="./../server/project-layout#configlua-the-startup-script">Project layout</a>.</p><h3 id="nitr-ext" tabindex="-1"><code>nitr.ext</code> <a class="header-anchor" href="#nitr-ext" aria-label="Permalink to “nitr.ext”">​</a></h3><p>User-defined Rust extension modules registered with <code>ServerBuilder::module</code>, one level below the standard library so no future builtin can collide with them. Each module is a table: <code>nitr.ext.&lt;name&gt;</code>. Absent until a module is registered. See <a href="./../library/extension-modules">Extension modules</a>.</p><hr><h2 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h2><h3 id="nitr-json" tabindex="-1"><code>nitr.json</code> <a class="header-anchor" href="#nitr-json" aria-label="Permalink to “nitr.json”">​</a></h3><p><code>nitr.json(value, status?) -&gt; nitr.Response</code> — <em>(std feature: <code>json</code>)</em></p><p>As a function: a JSON response (<code>nitr.json({ ok = true })</code>). Also the codec:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.json:encode(value) -&gt; string</code></td><td>Encodes a value as JSON.</td></tr><tr><td><code>nitr.json:decode(s) -&gt; any</code></td><td>Decodes JSON; errors on invalid input.</td></tr></tbody></table><h3 id="nitr-text" tabindex="-1"><code>nitr.text</code> <a class="header-anchor" href="#nitr-text" aria-label="Permalink to “nitr.text”">​</a></h3><p><code>nitr.text(body, status?) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>A <code>text/plain</code> response.</p><h3 id="nitr-html" tabindex="-1"><code>nitr.html</code> <a class="header-anchor" href="#nitr-html" aria-label="Permalink to “nitr.html”">​</a></h3><p><code>nitr.html(body, status?) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>A <code>text/html</code> response.</p><h3 id="nitr-redirect" tabindex="-1"><code>nitr.redirect</code> <a class="header-anchor" href="#nitr-redirect" aria-label="Permalink to “nitr.redirect”">​</a></h3><p><code>nitr.redirect(location, status?) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>A redirect; default <code>302</code>.</p><h3 id="nitr-status" tabindex="-1"><code>nitr.status</code> <a class="header-anchor" href="#nitr-status" aria-label="Permalink to “nitr.status”">​</a></h3><p><code>nitr.status(code) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>An empty response with the given status.</p><h3 id="nitr-error" tabindex="-1"><code>nitr.error</code> <a class="header-anchor" href="#nitr-error" aria-label="Permalink to “nitr.error”">​</a></h3><p><code>nitr.error(code, body?) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>An error response: a string body is sent as text, a table body as JSON.</p><h3 id="nitr-negotiate" tabindex="-1"><code>nitr.negotiate</code> <a class="header-anchor" href="#nitr-negotiate" aria-label="Permalink to “nitr.negotiate”">​</a></h3><p><code>nitr.negotiate(req, offers) -&gt; any</code> — <em>(std feature: <code>http</code>)</em></p><p>Picks the offer whose media type best matches the <code>Accept</code> header; function values are called with the request. No match answers <code>406</code>.</p><h3 id="nitr-etag" tabindex="-1"><code>nitr.etag</code> <a class="header-anchor" href="#nitr-etag" aria-label="Permalink to “nitr.etag”">​</a></h3><p><code>nitr.etag(value, weak?) -&gt; string</code> — <em>(std feature: <code>http</code>)</em></p><p>A well-formed entity tag for whatever identifies the resource — a row version, an <code>updated_at</code> — to pair with <a href="./types#nitr-request"><code>req:fresh</code></a>.</p><h3 id="nitr-sse" tabindex="-1"><code>nitr.sse</code> <a class="header-anchor" href="#nitr-sse" aria-label="Permalink to “nitr.sse”">​</a></h3><p><code>nitr.sse(fn) -&gt; nitr.Response</code> — <em>(std feature: <code>http</code>)</em></p><p>A Server-Sent Events stream: <code>fn(send)</code> calls <code>send(event, data)</code>; table data is JSON-encoded. See <a href="./../server/streaming">Streaming &amp; SSE</a>.</p><hr><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h2><h3 id="nitr-crypto" tabindex="-1"><code>nitr.crypto</code> <a class="header-anchor" href="#nitr-crypto" aria-label="Permalink to “nitr.crypto”">​</a></h3><p><em>(std feature: <code>crypto</code>)</em> — Crypto primitives from RustCrypto. Compose them; never reimplement them in Lua. See <a href="./../server/crypto-auth">Crypto &amp; auth</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.crypto.sha256(data) -&gt; string</code></td><td>SHA-256 digest, lowercase hex.</td></tr><tr><td><code>nitr.crypto.hmac_sha256(key, data) -&gt; string</code></td><td>HMAC-SHA256, lowercase hex.</td></tr><tr><td><code>nitr.crypto.random_bytes(n) -&gt; string</code></td><td><code>n</code> random bytes from the OS (1..=65536).</td></tr><tr><td><code>nitr.crypto.constant_time_eq(a, b) -&gt; boolean</code></td><td>Timing-safe comparison — what <code>==</code> on secrets is not.</td></tr><tr><td><code>nitr.crypto.password_hash(password) -&gt; string</code></td><td>argon2id hash for storage.</td></tr><tr><td><code>nitr.crypto.password_verify(password, hash) -&gt; boolean</code></td><td>Verifies a password against a stored hash.</td></tr><tr><td><code>nitr.crypto.seal(key, plaintext, aad?) -&gt; string</code></td><td>Authenticated encryption (XChaCha20-Poly1305); printable token.</td></tr><tr><td><code>nitr.crypto.open(key, sealed, aad?) -&gt; string|nil</code></td><td>Opens a sealed token; <code>nil</code> on any tampering.</td></tr></tbody></table><h3 id="nitr-crypto-jwt" tabindex="-1"><code>nitr.crypto.jwt</code> <a class="header-anchor" href="#nitr-crypto-jwt" aria-label="Permalink to “nitr.crypto.jwt”">​</a></h3><p><em>(std feature: <code>crypto</code>)</em> — HMAC JWTs (HS256/384/512). Verification demands an explicit algorithm allow-list; <code>exp</code> and <code>nbf</code> are checked by default.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.crypto.jwt.sign(claims, key, opts?) -&gt; string</code></td><td>Signs a token.</td></tr><tr><td><code>nitr.crypto.jwt.verify(token, key, opts) -&gt; table|nil, string|nil</code></td><td>Verifies a token.</td></tr></tbody></table><h3 id="nitr-auth" tabindex="-1"><code>nitr.auth</code> <a class="header-anchor" href="#nitr-auth" aria-label="Permalink to “nitr.auth”">​</a></h3><p><em>(std feature: <code>crypto</code>)</em> — <code>Authorization</code> header parsing.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.auth.basic(req) -&gt; string|nil, string|nil</code></td><td>Basic credentials, or <code>nil</code>.</td></tr><tr><td><code>nitr.auth.bearer(req) -&gt; string|nil</code></td><td>The bearer token, or <code>nil</code>.</td></tr></tbody></table><h3 id="nitr-csrf" tabindex="-1"><code>nitr.csrf</code> <a class="header-anchor" href="#nitr-csrf" aria-label="Permalink to “nitr.csrf”">​</a></h3><p><code>nitr.csrf(opts) -&gt; fun</code> — <em>(std feature: <code>http</code>)</em></p><p>As a function: the CSRF middleware factory for <code>app:use</code> — a signed double-submit cookie; unsafe methods must echo the token in <code>X-CSRF-Token</code> or a <code>_csrf</code> field. Options: <code>secret</code> (required), <code>cookie</code>, <code>header</code>, <code>field</code>, <code>cookie_opts</code>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.csrf.token(req) -&gt; string</code></td><td>The request&#39;s token, for a form or meta tag. Requires the middleware.</td></tr></tbody></table><h3 id="nitr-session" tabindex="-1"><code>nitr.session</code> <a class="header-anchor" href="#nitr-session" aria-label="Permalink to “nitr.session”">​</a></h3><p><code>nitr.session(req, opts) -&gt; nitr.Session</code> — <em>(std feature: <code>http</code>)</em></p><p>Loads (or starts) the stateless signed-cookie session. Options: <code>secret</code> (required), <code>name</code>, <code>max_age</code>, <code>cookie</code>. See <a href="./types#nitr-session"><code>nitr.Session</code></a>.</p><hr><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to “Data”">​</a></h2><h3 id="nitr-db" tabindex="-1"><code>nitr.db</code> <a class="header-anchor" href="#nitr-db" aria-label="Permalink to “nitr.db”">​</a></h3><p><em>(std feature: <code>db</code>)</em> — SQLite (<code>[database] path</code>): WAL, busy timeout, foreign keys on. See <a href="./../server/database">Database</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.db:execute(sql, params?) -&gt; integer</code></td><td>Runs a statement; returns the affected row count.</td></tr><tr><td><code>nitr.db:query(sql, params?) -&gt; table[]</code></td><td>All rows, each a column→value table.</td></tr><tr><td><code>nitr.db:query_row(sql, params?) -&gt; table|nil</code></td><td>The first row, or <code>nil</code>.</td></tr><tr><td><code>nitr.db:query_one(sql, params?) -&gt; any</code></td><td>The first column of the first row.</td></tr><tr><td><code>nitr.db:transaction(fn) -&gt; any</code></td><td>Runs <code>fn(tx)</code> atomically; rolls back on error. Nestable via savepoints. Use <code>tx</code>, not the outer <code>nitr.db</code>.</td></tr><tr><td><code>nitr.db:query_async(sql, params?, kind?) -&gt; table</code></td><td>An unsent query, to run alongside fetches in <code>nitr.await_all</code>.</td></tr></tbody></table><h3 id="nitr-cache" tabindex="-1"><code>nitr.cache</code> <a class="header-anchor" href="#nitr-cache" aria-label="Permalink to “nitr.cache”">​</a></h3><p><em>(std feature: <code>cache</code>)</em> — The bounded TTL + LRU cache shared by every state. Entries are plain data; per-process, so <strong>not</strong> a session store. See <a href="./../server/cache">Cache</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.cache:get(key) -&gt; any</code></td><td>The cached value, or <code>nil</code>.</td></tr><tr><td><code>nitr.cache:set(key, value, ttl?)</code></td><td>Stores a value; <code>ttl</code> in seconds.</td></tr><tr><td><code>nitr.cache:delete(key)</code></td><td>Removes a key.</td></tr><tr><td><code>nitr.cache:clear()</code></td><td>Empties the cache.</td></tr><tr><td><code>nitr.cache:remember(key, ttl, fn) -&gt; any</code></td><td>The cached value, or <code>fn()</code>&#39;s result, stored and returned.</td></tr><tr><td><code>nitr.cache:stats() -&gt; table</code></td><td>Hit / miss / entry counters.</td></tr></tbody></table><h3 id="nitr-validate" tabindex="-1"><code>nitr.validate</code> <a class="header-anchor" href="#nitr-validate" aria-label="Permalink to “nitr.validate”">​</a></h3><p><em>(std feature: <code>validate</code>)</em> — Declarative validation, compiled once and checked in Rust. See <a href="./../server/validation">Validation</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.validate.schema(fields) -&gt; nitr.Schema</code></td><td>Compiles a schema.</td></tr></tbody></table><hr><h2 id="i-o" tabindex="-1">I/O <a class="header-anchor" href="#i-o" aria-label="Permalink to “I/O”">​</a></h2><h3 id="nitr-fetch" tabindex="-1"><code>nitr.fetch</code> <a class="header-anchor" href="#nitr-fetch" aria-label="Permalink to “nitr.fetch”">​</a></h3><p><code>nitr.fetch(method, url, opts?) -&gt; nitr.FetchHandle</code> — <em>(std feature: <code>fetch</code>)</em></p><p>An outbound HTTP request — SSRF-guarded, redirect-checked. Options: <code>headers</code>, <code>query</code>, <code>json</code>, <code>body</code>, <code>timeout</code>, <code>retry</code>. Returns an <strong>unsent</strong> handle. See <a href="./../server/fetch">Outbound HTTP</a>.</p><h3 id="nitr-await-all" tabindex="-1"><code>nitr.await_all</code> <a class="header-anchor" href="#nitr-await-all" aria-label="Permalink to “nitr.await_all”">​</a></h3><p><code>nitr.await_all(handles) -&gt; table</code> — <em>(std feature: <code>fetch</code>)</em></p><p>Runs fetch handles (and <code>db:query_async</code> handles) concurrently; returns their results in order.</p><h3 id="nitr-template" tabindex="-1"><code>nitr.template</code> <a class="header-anchor" href="#nitr-template" aria-label="Permalink to “nitr.template”">​</a></h3><p><em>(std feature: <code>template</code>)</em> — The minijinja template engine, loading from <code>[templating] dir</code>. See <a href="./../server/templates">Templates</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.template:render(name, data?) -&gt; string</code></td><td>Renders a template.</td></tr></tbody></table><hr><h2 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to “Utilities”">​</a></h2><h3 id="nitr-time" tabindex="-1"><code>nitr.time</code> <a class="header-anchor" href="#nitr-time" aria-label="Permalink to “nitr.time”">​</a></h3><p><em>(std feature: <code>time</code>)</em> — Safe clocks and time formatting (UTC), so scripts never need the <code>os</code> library for a date.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.time.now() -&gt; integer</code></td><td>Unix seconds.</td></tr><tr><td><code>nitr.time.monotonic() -&gt; number</code></td><td>Monotonic seconds, sub-second precision — for measuring durations.</td></tr><tr><td><code>nitr.time.format(ts, fmt) -&gt; string</code></td><td>Formats a timestamp in UTC.</td></tr><tr><td><code>nitr.time.parse(value, fmt) -&gt; integer|nil, string|nil</code></td><td>Parses per a strftime format (UTC unless the input carries an offset).</td></tr><tr><td><code>nitr.time.http(ts) -&gt; string</code></td><td>IMF-fixdate (<code>Tue, 15 Nov 1994 08:12:31 GMT</code>).</td></tr><tr><td><code>nitr.time.parse_http(value) -&gt; integer|nil</code></td><td>Parses the three HTTP date forms.</td></tr><tr><td><code>nitr.time.iso8601(ts) -&gt; string</code></td><td>RFC 3339 in UTC (<code>1994-11-15T08:12:31Z</code>).</td></tr></tbody></table><h3 id="nitr-base64" tabindex="-1"><code>nitr.base64</code> <a class="header-anchor" href="#nitr-base64" aria-label="Permalink to “nitr.base64”">​</a></h3><p><em>(std feature: <code>base64</code>)</em></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.base64.encode(data, opts?) -&gt; string</code></td><td>Encodes bytes. <code>{ url = true }</code> selects the URL-safe alphabet.</td></tr><tr><td><code>nitr.base64.decode(value, opts?) -&gt; string|nil, string|nil</code></td><td>Decodes; forgiving about padding, never about the alphabet.</td></tr></tbody></table><h3 id="nitr-path" tabindex="-1"><code>nitr.path</code> <a class="header-anchor" href="#nitr-path" aria-label="Permalink to “nitr.path”">​</a></h3><p><em>(std feature: <code>path</code>)</em> — Lexical path manipulation, POSIX and Windows styles. Pure text: <strong>nothing touches the filesystem</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.path.join(...) -&gt; string</code></td><td>Joins segments; a later absolute segment never discards the base.</td></tr><tr><td><code>nitr.path.basename(path) -&gt; string</code></td><td>The final component.</td></tr><tr><td><code>nitr.path.dirname(path) -&gt; string</code></td><td>The directory part.</td></tr><tr><td><code>nitr.path.extension(path) -&gt; string|nil</code></td><td>The extension without the dot; <code>nil</code> for none, dotfiles included.</td></tr><tr><td><code>nitr.path.normalize(path) -&gt; string</code></td><td>Resolves <code>.</code> and <code>..</code> lexically; <code>..</code> cannot climb out of the root.</td></tr><tr><td><code>nitr.path.is_absolute(path) -&gt; boolean</code></td><td>Whether the path is absolute (<code>/x</code>, <code>C:\\x</code>, UNC).</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">`normalize` is text-only</p><p></p><p>Before real file access on Windows, also reject segments with trailing dots or spaces, or colons — Win32 rewrites those.</p></div><h3 id="nitr-url" tabindex="-1"><code>nitr.url</code> <a class="header-anchor" href="#nitr-url" aria-label="Permalink to “nitr.url”">​</a></h3><p><em>(std feature: <code>url</code>)</em> — Percent-encoding, query strings, and a lexical URL splitter.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.url.encode(value) -&gt; string</code></td><td>Percent-encodes a component (like <code>encodeURIComponent</code>).</td></tr><tr><td><code>nitr.url.decode(value) -&gt; string</code></td><td>Percent-decodes; <code>+</code> is left alone — that is a form convention.</td></tr><tr><td><code>nitr.url.query_parse(query) -&gt; table&lt;string, string&gt;</code></td><td>Parses a query string; <code>+</code> as space, last duplicate wins.</td></tr><tr><td><code>nitr.url.query_build(params) -&gt; string</code></td><td>Builds a query string, keys sorted.</td></tr><tr><td><code>nitr.url.parse(value) -&gt; table|nil, string|nil</code></td><td>Splits a URL lexically — not a WHATWG parser. Returns <code>{ scheme?, userinfo?, host?, port?, path, query?, fragment? }</code>.</td></tr></tbody></table><h3 id="nitr-env" tabindex="-1"><code>nitr.env</code> <a class="header-anchor" href="#nitr-env" aria-label="Permalink to “nitr.env”">​</a></h3><p><em>(std feature: <code>env</code>)</em> — Read-only environment access. Opt-in; reads are filtered by <code>[env] allow</code>, and <code>NITR_*</code> internals are never visible. Getters only: no setter, no enumeration. See <a href="./../server/configuration/env#the-nitrenv-builtin">Environment variables</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.env.get(name, default?) -&gt; string|nil</code></td><td>Reads one variable.</td></tr><tr><td><code>nitr.env.has(name) -&gt; boolean</code></td><td>Whether it is set <strong>and readable</strong>; a policy-hidden name reports <code>false</code>.</td></tr><tr><td><code>nitr.env.number(name, default?) -&gt; number|nil</code></td><td>Reads and parses a number; unset or unparseable answers the default.</td></tr><tr><td><code>nitr.env.bool(name, default?) -&gt; boolean|nil</code></td><td>Reads a flag: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code> and <code>0</code>/<code>false</code>/<code>no</code>/<code>off</code>, any case.</td></tr></tbody></table><hr><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “Diagnostics”">​</a></h2><h3 id="nitr-log" tabindex="-1"><code>nitr.log</code> <a class="header-anchor" href="#nitr-log" aria-label="Permalink to “nitr.log”">​</a></h3><p><em>(std feature: <code>log</code>)</em> — Structured logging into the request span. Fields become real keys in JSON log output. See <a href="./../server/logging">Logging</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.log.debug(msg, fields?)</code></td><td>Debug-level record.</td></tr><tr><td><code>nitr.log.info(msg, fields?)</code></td><td>Info-level record.</td></tr><tr><td><code>nitr.log.warn(msg, fields?)</code></td><td>Warn-level record.</td></tr><tr><td><code>nitr.log.error(msg, fields?)</code></td><td>Error-level record.</td></tr></tbody></table><h3 id="nitr-dbg" tabindex="-1"><code>nitr.dbg</code> <a class="header-anchor" href="#nitr-dbg" aria-label="Permalink to “nitr.dbg”">​</a></h3><p><code>nitr.dbg(value) -&gt; any</code> — <em>(std feature: <code>dbg</code>)</em></p><p>Debug-prints a value, structure included, to the log; returns it unchanged.</p><h3 id="nitr-errinfo" tabindex="-1"><code>nitr.errinfo</code> <a class="header-anchor" href="#nitr-errinfo" aria-label="Permalink to “nitr.errinfo”">​</a></h3><p><code>nitr.errinfo(caught) -&gt; table</code></p><p>Classifies a <code>pcall</code>-caught error into its structured form: <code>kind</code>, <code>message</code>, <code>source</code>, <code>line</code>, <code>traceback</code>, <code>cause</code>, <code>pretty</code>. See <a href="./../server/errors">Errors</a>.</p><hr><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to “Testing”">​</a></h2><h3 id="nitr-test" tabindex="-1"><code>nitr.test</code> <a class="header-anchor" href="#nitr-test" aria-label="Permalink to “nitr.test”">​</a></h3><p><em>(available in <code>nitr test</code> files only)</em> — See <a href="./../server/testing">Testing</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>nitr.test.request(method, path, opts?) -&gt; table</code></td><td>Dispatches through the real router / middleware / handler path. Options: <code>headers</code>, <code>body</code>, <code>json</code>. Returns <code>{ status, headers, body }</code> plus <code>:json()</code>.</td></tr><tr><td><code>nitr.test.describe(name, fn)</code></td><td>Groups tests; names are prefixed.</td></tr><tr><td><code>nitr.test.it(name, fn)</code></td><td>One test case.</td></tr><tr><td><code>nitr.test.expect(actual) -&gt; table</code></td><td>Starts an assertion. Matchers: <code>to_equal</code>, <code>to_not_equal</code>, <code>to_be_nil</code>, <code>to_be_truthy</code>, <code>to_match</code>, <code>to_contain</code>.</td></tr><tr><td><code>nitr.test.before_each(fn)</code></td><td>Runs before every test in the file.</td></tr><tr><td><code>nitr.test.after_each(fn)</code></td><td>Runs after every test in the file, failing ones included.</td></tr></tbody></table>',121)])])}const f=t(o,[["render",n]]);export{b as __pageData,f as default};
